from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class Counters(SchemaObject):
    id = SchemaField(name='id')
    abbreviation = SchemaField(name='abbreviation')
    unit = SchemaField(name='unit')

    def __init__(self, id, abbreviation, unit):
        self.id = id
        self.abbreviation = abbreviation
        self.unit = unit

        super(Counters, self).__init__()


class MeasurementsPMV2(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    abbreviation = SchemaField(name='abbreviation', not_null=True)
    name = SchemaField(name='name', not_null=True)
    network_profile = SchemaField(name='network_profile', not_null=True, many=True)
    measurement_group = SchemaField(name='measurement_group', not_null=True)
    counters = SchemaField(name='counters', klass=Counters, many=True)

    def __init__(self, id, abbreviation, name, network_profile, measurement_group, counters):
        self.id = id
        self.abbreviation = abbreviation
        self.name = name
        self.network_profile = network_profile
        self.measurement_group = measurement_group
        self.counters = counters

        super(MeasurementsPMV2, self).__init__()
